"""Run-time support for code generated by neoc.

Generated modules import only this module.  Everything here is a check or a
mechanism the compiler could not settle on its own.  Set ``NEO_CHECKS=0`` to
turn every run-time check off; it is read when a decorated function is
defined, so the checks cost nothing afterwards.
"""

from __future__ import annotations

import asyncio
import functools
import importlib
import inspect
import multiprocessing
import os
import pickle
import sys
import threading
import traceback
import types
import typing
from collections.abc import Awaitable, Callable, Coroutine, Mapping, Sequence
from collections.abc import Set as AbstractSet
from concurrent.futures import ProcessPoolExecutor, ThreadPoolExecutor
from concurrent.futures.process import BrokenProcessPool
from dataclasses import dataclass
from multiprocessing.reduction import ForkingPickler
from types import MappingProxyType
from typing import Any, Generic, ParamSpec, TypeVar, overload

if sys.version_info >= (3, 14):
    import annotationlib
else:
    annotationlib = None

__all__ = [
    "AbstractSet", "CheckError", "ComputeError", "ComputeFunction", "Mapping", "MappingProxyType", "PickleCheckError", "Scope",
    "Sequence", "isolated",
    "checked", "checks_enabled", "compute", "compute_pool", "scope", "shutdown_compute_pool",
]

P = ParamSpec("P")
R = TypeVar("R")
T = TypeVar("T")
F = TypeVar("F", bound=Callable[..., Any])


def checks_enabled() -> bool:
    return os.environ.get("NEO_CHECKS", "1").strip().lower() not in {"0", "false", "no", "off"}


# --- frozen values --------------------------------------------------------------
#
# ``val`` dict literals compile to MappingProxyType, which plain pickle refuses.
# Registering it with the multiprocessing pickler lets frozen dicts travel to
# compute workers (and back) without affecting pickling anywhere else.


def _rebuild_mappingproxy(data: dict[Any, Any]) -> MappingProxyType[Any, Any]:
    return MappingProxyType(data)


def _reduce_mappingproxy(
    proxy: MappingProxyType[Any, Any],
) -> tuple[Callable[[dict[Any, Any]], MappingProxyType[Any, Any]], tuple[dict[Any, Any]]]:
    return _rebuild_mappingproxy, (dict(proxy),)


ForkingPickler.register(MappingProxyType, _reduce_mappingproxy)


# --- @checked --------------------------------------------------------------------


class CheckError(TypeError):
    """An argument of a ``@neo.checked`` function has the wrong type."""


_NUMERIC_PROMOTIONS: dict[type, tuple[type, ...]] = {float: (float, int), complex: (complex, float, int)}


def _runtime_types(hint: Any) -> tuple[type, ...] | None:
    """The classes to pass to ``isinstance`` for a hint, or None to skip the check.

    The check is shallow: ``list[int]`` only checks for ``list``.
    """
    if hint is None or hint is type(None):
        return (type(None),)
    if hint is Any or hint is object:
        return None
    origin = typing.get_origin(hint)
    if origin is typing.Annotated:
        return _runtime_types(typing.get_args(hint)[0])
    if origin is typing.Union or origin is types.UnionType:
        found: list[type] = []
        for arg in typing.get_args(hint):
            part = _runtime_types(arg)
            if part is None:
                return None
            found += part
        return tuple(dict.fromkeys(found))
    if origin is typing.Literal:
        return tuple(dict.fromkeys(type(value) for value in typing.get_args(hint)))
    if origin is not None:
        hint = origin
    if isinstance(hint, TypeVar):
        if hint.__bound__ is not None:
            return _runtime_types(hint.__bound__)
        return _runtime_types(typing.Union[hint.__constraints__]) if hint.__constraints__ else None
    supertype = getattr(hint, "__supertype__", None)  # typing.NewType
    if supertype is not None:
        return _runtime_types(supertype)
    if not isinstance(hint, type):
        return None
    if typing.is_typeddict(hint):
        return (dict,)
    if hint in _NUMERIC_PROMOTIONS:
        return _NUMERIC_PROMOTIONS[hint]
    if getattr(hint, "_is_protocol", False) and not getattr(hint, "_is_runtime_protocol", False):
        return None
    try:
        isinstance(None, hint)
    except TypeError:
        return None
    return (hint,)


def _type_hints(fn: Callable[..., Any]) -> dict[str, Any]:
    try:
        return typing.get_type_hints(fn)
    except Exception:
        pass
    # Some annotation does not resolve; keep the ones that do.
    if annotationlib is not None:
        raw = annotationlib.get_annotations(fn, format=annotationlib.Format.FORWARDREF)
    else:
        raw = dict(getattr(fn, "__annotations__", {}))
    return {name: hint for name, hint in raw.items() if not isinstance(hint, (str, typing.ForwardRef))}


@dataclass(frozen=True)
class _Plan:
    positional: tuple[tuple[int, str, bool, tuple[type, ...]], ...]  # index, name, positional-only, types
    keyword: tuple[tuple[str, tuple[type, ...]], ...]
    varargs: tuple[int, tuple[type, ...]] | None  # first extra index, types
    varkw: tuple[frozenset[str], tuple[type, ...]] | None  # named parameters, types


def _plan(fn: Callable[..., Any]) -> _Plan:
    code = fn.__code__
    hints = _type_hints(fn)
    names = code.co_varnames
    npos, nkw = code.co_argcount, code.co_kwonlyargcount

    def types_for(name: str) -> tuple[type, ...] | None:
        return _runtime_types(hints[name]) if name in hints else None

    positional = []
    for index in range(npos):
        if (expected := types_for(names[index])) is not None:
            positional.append((index, names[index], index < code.co_posonlyargcount, expected))
    keyword = []
    for name in names[npos : npos + nkw]:
        if (expected := types_for(name)) is not None:
            keyword.append((name, expected))
    index = npos + nkw
    varargs = varkw = None
    if code.co_flags & inspect.CO_VARARGS:
        if (expected := types_for(names[index])) is not None:
            varargs = (npos, expected)
        index += 1
    if code.co_flags & inspect.CO_VARKEYWORDS:
        if (expected := types_for(names[index])) is not None:
            varkw = (frozenset(names[code.co_posonlyargcount : npos + nkw]), expected)
    return _Plan(tuple(positional), tuple(keyword), varargs, varkw)


def _fail(fn: Callable[..., Any], name: str, value: Any, expected: tuple[type, ...]) -> CheckError:
    wanted = " | ".join("None" if t is type(None) else t.__qualname__ for t in expected)
    return CheckError(f"{fn.__qualname__}() argument '{name}' must be {wanted}, not {type(value).__qualname__}")


def _check(fn: Callable[..., Any], plan: _Plan, args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
    for index, name, positional_only, expected in plan.positional:
        if index < len(args):
            value = args[index]
        elif not positional_only and name in kwargs:
            value = kwargs[name]
        else:
            continue  # the default is used
        if not isinstance(value, expected):
            raise _fail(fn, name, value, expected)
    for name, expected in plan.keyword:
        if name in kwargs and not isinstance(kwargs[name], expected):
            raise _fail(fn, name, kwargs[name], expected)
    if plan.varargs is not None:
        start, expected = plan.varargs
        for offset, value in enumerate(args[start:]):
            if not isinstance(value, expected):
                raise _fail(fn, f"*args[{offset}]", value, expected)
    if plan.varkw is not None:
        named, expected = plan.varkw
        for name, value in kwargs.items():
            if name not in named and not isinstance(value, expected):
                raise _fail(fn, name, value, expected)


def checked(fn: F) -> F:
    """Check annotated arguments with ``isinstance`` on every call.

    Only functions carrying this decorator are checked, and only one level
    deep.  With ``NEO_CHECKS=0`` the function is returned unchanged.
    """
    if not checks_enabled():
        return fn
    target = inspect.unwrap(fn)
    if not hasattr(target, "__code__"):
        raise TypeError(f"@neo.checked expects a function, got {fn!r}")
    plan: _Plan | None = None

    def check(args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
        nonlocal plan
        if plan is None:  # resolved on first call, so forward references work
            plan = _plan(target)
        _check(target, plan, args, kwargs)

    if inspect.iscoroutinefunction(fn) and sys.version_info < (3, 12):  # no markcoroutinefunction
        @functools.wraps(fn)
        async def async_wrapper(*args: Any, **kwargs: Any) -> Any:
            check(args, kwargs)
            return await fn(*args, **kwargs)

        return typing.cast(F, async_wrapper)

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        check(args, kwargs)
        return fn(*args, **kwargs)

    if inspect.iscoroutinefunction(fn):
        inspect.markcoroutinefunction(wrapper)
    return typing.cast(F, wrapper)


# --- compute -----------------------------------------------------------------------


class PickleCheckError(TypeError):
    """NEO2004 at run time: a compute argument or result cannot be pickled."""


class ComputeError(Exception):
    """A compute job ended in a way that cannot be handed back as it is: it
    called ``sys.exit()``, or raised an exception the caller cannot rebuild.
    The worker's traceback, original exception included, comes with it."""


_pool: ProcessPoolExecutor | None = None
_pool_lock = threading.Lock()


def _start_method() -> str:
    # forkserver (the default on Linux since 3.14) wherever it exists, so compute
    # behaves the same on every Python version: workers import functions by name.
    return "forkserver" if "forkserver" in multiprocessing.get_all_start_methods() else "spawn"


def compute_pool() -> ProcessPoolExecutor:
    """The process pool shared by every compute function, created on first use."""
    global _pool
    with _pool_lock:
        if _pool is None:
            _pool = ProcessPoolExecutor(mp_context=multiprocessing.get_context(_start_method()))
        return _pool


def shutdown_compute_pool(wait: bool = True) -> None:
    global _pool, _waiters
    with _pool_lock:
        pool, _pool = _pool, None
        waiters, _waiters = _waiters, None
    if pool is not None:
        pool.shutdown(wait=wait)
    if waiters is not None:
        waiters.shutdown(wait=wait)


def _discard_broken_pool(pool: ProcessPoolExecutor) -> None:
    """A worker died, which breaks the whole pool; the next call gets a new one."""
    global _pool
    with _pool_lock:
        if _pool is pool:  # another call may already have replaced it
            _pool = None
    pool.shutdown(wait=False, cancel_futures=True)


def _ensure_picklable(value: Any, what: str) -> None:
    try:
        ForkingPickler.dumps(value)
    except Exception as exc:
        raise PickleCheckError(f"NEO2004: {what} cannot be pickled: {exc}") from None


def _lookup(module: str, qualname: str) -> Any:
    found: Any = importlib.import_module(module)
    for part in qualname.split("."):
        found = getattr(found, part)
    return found


def _round_trips(exc: BaseException) -> bool:
    try:
        pickle.loads(ForkingPickler.dumps(exc))
    except Exception:
        return False
    return True


def _invoke(function: ComputeFunction[..., Any], args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
    """Runs in the worker process."""
    name = function.__qualname__
    try:
        result = function.__wrapped__(*args, **kwargs)
    except SystemExit as exc:
        # Passed on as it is, SystemExit would stop the caller's whole program.
        raise ComputeError(f"compute '{name}' called sys.exit({exc.code!r})")
    except Exception as exc:
        # An exception the caller cannot rebuild (say, one whose __init__ takes
        # two arguments) would otherwise break the pool for every other job.
        if not _round_trips(exc):
            raise ComputeError(
                f"compute '{name}' raised {type(exc).__qualname__}: {exc} "
                "(the exception itself cannot be sent back, so this one stands in for it)"
            )
        raise
    if function.check_result:
        _ensure_picklable(result, f"the result of compute '{function.__qualname__}'")
    return result


def _signature(fn: Callable[..., Any]) -> inspect.Signature:
    if annotationlib is not None:
        return inspect.signature(fn, annotation_format=annotationlib.Format.FORWARDREF)
    return inspect.signature(fn)


# --- isolated compute ---------------------------------------------------------------
#
# The shared pool cannot stop one job: it does not say which worker runs it,
# and killing a worker breaks every other job.  ``@neo.isolated`` pays for a
# process start on each call and gets a job that can really be stopped.


def isolated(fn: F) -> F:
    """Run each call of this ``compute def`` in a process of its own.

    Cancelling the call, or letting it time out, kills that process: the CPU
    is free again at once, and no other call is touched.
    """
    setattr(fn, "__neo_isolated__", True)
    return fn


_waiters: ThreadPoolExecutor | None = None


def _isolated_waiters() -> ThreadPoolExecutor:
    """Threads that start and wait on isolated processes; their number caps how
    many isolated processes run at once."""
    global _waiters
    with _pool_lock:
        if _waiters is None:
            _waiters = ThreadPoolExecutor(max_workers=os.cpu_count() or 1, thread_name_prefix="neo-isolated")
        return _waiters


class _RemoteTraceback(Exception):
    def __str__(self) -> str:
        return str(self.args[0])


def _isolated_main(sender: Any, function: ComputeFunction[..., Any], args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
    """Runs in the isolated process: one call, one answer through the pipe."""
    try:
        message = (True, _invoke(function, args, kwargs), "")
    except BaseException as exc:
        message = (False, exc, traceback.format_exc())
    try:
        sender.send(message)
    except Exception as exc:
        what = "the result" if message[0] else "the exception"
        error = PickleCheckError(f"NEO2004: {what} of compute '{function.__qualname__}' cannot be pickled: {exc}")
        sender.send((False, error, ""))
    finally:
        sender.close()


class _IsolatedCall:
    """One isolated call.  A waiter thread starts and reaps the process; a
    cancelled caller kills it."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._process: Any = None
        self._cancelled = False

    def cancel(self) -> None:
        with self._lock:
            self._cancelled = True
            if self._process is not None:
                self._process.kill()

    def run(self, function: ComputeFunction[..., Any], args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
        # typeshed declares get_context() as BaseContext, which lacks Process.
        context: Any = multiprocessing.get_context(_start_method())
        receiver, sender = context.Pipe(duplex=False)
        with self._lock:
            if self._cancelled:  # cancelled before this thread got to it
                receiver.close()
                sender.close()
                return None
            process = self._process = context.Process(target=_isolated_main, args=(sender, function, args, kwargs))
            process.start()
        sender.close()
        try:
            ok, value, remote = receiver.recv()
        except EOFError:  # killed, or died without answering
            ok, value, remote = None, None, ""
        finally:
            receiver.close()
            process.join()  # reaped, so no zombie is left behind
        if ok is None:
            raise BrokenProcessPool(
                f"the process of isolated compute '{function.__qualname__}' exited with code {process.exitcode}"
            )
        if not ok:
            if remote:
                value.__cause__ = _RemoteTraceback(remote)
            raise value
        return value


class ComputeFunction(Generic[P, R]):
    """A ``compute def``.  Calling it returns a coroutine that runs the body
    in the shared process pool, so ``await f(x)`` and ``s.spawn(f(x))`` both work.

    It pickles by reference (module and qualified name), which is why a
    compute function has to live at module level.
    """

    __wrapped__: Callable[P, R]
    __qualname__: str  # set by functools.update_wrapper

    def __init__(self, fn: Callable[P, R], check_args: tuple[str, ...] = (), check_result: bool = False) -> None:
        functools.update_wrapper(self, fn)
        enabled = checks_enabled()
        self.check_args = check_args if enabled else ()
        self.check_result = check_result and enabled
        self.isolated = bool(getattr(fn, "__neo_isolated__", False))
        self._signature: inspect.Signature | None = None

    def __call__(self, *args: P.args, **kwargs: P.kwargs) -> Coroutine[Any, Any, R]:
        if self.check_args:
            self._check_arguments(args, kwargs)
        return self._run(args, kwargs)

    async def _run(self, args: tuple[Any, ...], kwargs: dict[str, Any]) -> R:
        loop = asyncio.get_running_loop()
        if self.isolated:
            call = _IsolatedCall()
            try:
                return await loop.run_in_executor(_isolated_waiters(), call.run, self, args, kwargs)
            except asyncio.CancelledError:
                call.cancel()
                raise
        pool = compute_pool()
        try:
            return await loop.run_in_executor(pool, functools.partial(_invoke, self, args, kwargs))
        except BrokenProcessPool:
            # This call fails and is not retried (it may be what crashed the
            # worker), but later calls must not inherit the broken pool.
            _discard_broken_pool(pool)
            raise

    def _check_arguments(self, args: tuple[Any, ...], kwargs: dict[str, Any]) -> None:
        if self._signature is None:
            self._signature = _signature(self.__wrapped__)
        bound = self._signature.bind(*args, **kwargs)
        for name in self.check_args:
            if name in bound.arguments:
                _ensure_picklable(bound.arguments[name], f"argument '{name}' of compute '{self.__qualname__}'")

    def __reduce__(self) -> tuple[Callable[[str, str], Any], tuple[str, str]]:
        return _lookup, (self.__module__, self.__qualname__)

    def __repr__(self) -> str:
        return f"<compute {self.__module__}.{self.__qualname__}>"


@overload
def compute(fn: Callable[P, R], /) -> ComputeFunction[P, R]: ...
@overload
def compute(
    *, check_args: tuple[str, ...] = (), check_result: bool = False
) -> Callable[[Callable[P, R]], ComputeFunction[P, R]]: ...
def compute(
    fn: Callable[P, R] | None = None, /, *, check_args: tuple[str, ...] = (), check_result: bool = False
) -> ComputeFunction[P, R] | Callable[[Callable[P, R]], ComputeFunction[P, R]]:
    """Mark a module-level function to run in the process pool.

    ``check_args`` names the parameters, and ``check_result`` the return value,
    whose picklability neoc could not prove from the type hints.
    """
    if fn is None:
        return lambda f: ComputeFunction(f, check_args, check_result)
    return ComputeFunction(fn, check_args, check_result)


# --- scope -----------------------------------------------------------------------


async def _await(awaitable: Awaitable[T]) -> T:
    return await awaitable


class Scope:
    """Structured concurrency on top of ``asyncio.TaskGroup``.

    Everything spawned in ``async with scope() as s:`` has finished when the
    block exits; ``s.results()`` then returns the results in spawn order.
    """

    def __init__(self) -> None:
        self._group = asyncio.TaskGroup()
        self._tasks: list[asyncio.Task[Any]] = []
        self._exited = False

    async def __aenter__(self) -> Scope:
        await self._group.__aenter__()
        return self

    async def __aexit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        try:
            await self._group.__aexit__(exc_type, exc, tb)
        finally:
            self._exited = True

    def __enter__(self) -> Scope:
        raise TypeError("scope() must be used with 'async with', not 'with'")

    def __exit__(self, *exc_info: Any) -> None:
        return None

    def spawn(self, awaitable: Awaitable[T]) -> asyncio.Task[T]:
        if self._exited:
            if asyncio.iscoroutine(awaitable):
                awaitable.close()  # as TaskGroup does, so it is not reported as never awaited
            raise RuntimeError("cannot spawn into a scope that has already exited")
        coroutine = awaitable if asyncio.iscoroutine(awaitable) else _await(awaitable)
        task = self._group.create_task(coroutine)
        self._tasks.append(task)
        return task

    def results(self) -> list[Any]:
        if not self._exited:
            raise RuntimeError("results() is available once the 'async with scope()' block has exited")
        return [task.result() for task in self._tasks]


def scope() -> Scope:
    return Scope()
